import subprocess
from types import SimpleNamespace

from code2req.repofiles import is_generated, list_repo_files
from code2req.structure import attach_declaration_files, keep_source_components


def write(root, files):
    for rel, text in files.items():
        p = root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(text)


FILES = {
    ".gitignore": "tmp/\n",
    "app/main.go": "package main\nfunc main() {}\n",
    "app/consts.go": "package main\nconst Limit = 5\n",
    "app/pb/api.pb.go": "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage pb\n",
    "app/registry_gen.go": "// Code generated by isqgen; DO NOT EDIT.\npackage main\n",
    "app/api_pb2.py": "x = 1\n",
    "tmp/copy/main.go": "package main\nfunc Copy() {}\n",          # ignored
    "scripts/scratch.py": "print('one-off')\n",                       # untracked
}


def repo(tmp_path):
    write(tmp_path, FILES)
    subprocess.run(["git", "init", "-q"], cwd=tmp_path, check=True)
    subprocess.run(["git", "add", ".gitignore", "app"], cwd=tmp_path, check=True)
    return tmp_path


def test_tracked_hand_written_files_only(tmp_path):
    r = list_repo_files(str(repo(tmp_path)))
    assert r.git
    assert r.files == [".gitignore", "app/consts.go", "app/main.go"]
    assert r.generated == ["app/api_pb2.py", "app/pb/api.pb.go", "app/registry_gen.go"]
    assert r.untracked_code == 1  # scripts/scratch.py; tmp/ is ignored, so not even counted
    assert "app/main.go" in r and "tmp/copy/main.go" not in r


def test_exclude_and_walk_without_git(tmp_path):
    write(tmp_path, {"a.py": "x = 1\n", "gen/b.py": "# @generated\nx = 2\n", "vendor/c.py": "x = 3\n"})
    r = list_repo_files(str(tmp_path), exclude=["a.py"])
    assert not r.git and r.files == [] and r.generated == ["gen/b.py"]
    assert is_generated(str(tmp_path), "gen/b.py") and not is_generated(str(tmp_path), "a.py")


def test_components_and_declaration_files_outside_the_list_are_dropped(tmp_path):
    root = repo(tmp_path)
    files = list_repo_files(str(root))
    node = lambda path, name: SimpleNamespace(relative_path=path, name=name, start_line=2, end_line=2,
                                              source_code="func x() {}", component_type="function")
    comps = {"m": node("app/main.go", "main"), "c": node("tmp/copy/main.go", "Copy"),
             "p": node("app/pb/api.pb.go", "Get")}
    kept, leaves = keep_source_components(comps, ["m", "c", "p"], files)
    assert list(kept) == ["m"] and leaves == ["m"]
    # The walk would also find tmp/ and the generated files; the list does not.
    mods = attach_declaration_files([], kept, str(root), files=files.files)
    assert [f for m in mods for f in m.extra_files] == ["app/consts.go"]
